(6196318, 914556, 33736, '<td valign="top">I scored this low, simply based on the exposure issues (but, added a point because you got the eyes so well.)  4</td>', 'I scored this low, simply based on the exposure issues (but, added a point because you got the eyes so well.)  4', '2010-10-20 02:38:22.000000', NULL, 1),
