(6196321, 914822, 33736, '<td valign="top">From where you''re taking this, it seems the traffic is too far away to have it relate to Sound as much as it does to Sight.</td>', 'From where you''re taking this, it seems the traffic is too far away to have it relate to Sound as much as it does to Sight.', '2010-10-20 02:43:01.000000', NULL, 1),
(6196323, 914771, 33736, '<td valign="top">The grunge look works well here, but there is a lot of "haloing" around his head and some strange white areas on his cheek and over his lip.</td>', 'The grunge look works well here, but there is a lot of "haloing" around his head and some strange white areas on his cheek and over his lip.', '2010-10-20 02:44:47.000000', NULL, 1),
