(6201814, 914725, 114225, '<td valign="top">Sorry, I''m just not understanding how this really fits the challenge. I don''t see any movement in the windmills, so I don''t know that they are "whooshing", and sunsets generally don''t make much noise.</td>', 'Sorry, I''m just not understanding how this really fits the challenge. I don''t see any movement in the windmills, so I don''t know that they are "whooshing", and sunsets generally don''t make much noise.', '2010-10-26 15:55:58.000000', NULL, 1),
(6201815, 915185, 114225, '<td valign="top">This is a very nice photo overall. Good colors, lighting, and composition. However, I''m not seeing a huge correlation between this and the challenge, so some points off for that.</td>', 'This is a very nice photo overall. Good colors, lighting, and composition. However, I''m not seeing a huge correlation between this and the challenge, so some points off for that.', '2010-10-26 15:56:45.000000', NULL, 1),
(6201817, 915225, 114225, '<td valign="top">Good clean/crisp photo with nice colors and details. I guess for the sound part, you were going for the flags flapping in the breeze. Not a very strong correlation there, in my humble opinion.</td>', 'Good clean/crisp photo with nice colors and details. I guess for the sound part, you were going for the flags flapping in the breeze. Not a very strong correlation there, in my humble opinion.', '2010-10-26 15:57:42.000000', NULL, 1),
(6201820, 915137, 114225, '<td valign="top">Very cool photo with a great mood, great colors, and perfect composition. However, I don''t find any hint of "sound" in a photo of a non-moving plane without even a pilot.</td>', 'Very cool photo with a great mood, great colors, and perfect composition. However, I don''t find any hint of "sound" in a photo of a non-moving plane without even a pilot.', '2010-10-26 15:58:31.000000', NULL, 1),
(6201821, 915386, 114225, '<td valign="top">Sorry, but in my opinion, silence is the complete lack of sound, and thus this isn''t meeting the challenge. This is a nice photo with good colors though.</td>', 'Sorry, but in my opinion, silence is the complete lack of sound, and thus this isn''t meeting the challenge. This is a nice photo with good colors though.', '2010-10-26 15:59:23.000000', NULL, 1),
