(6202117, 914704, 50695, '<td valign="top">Looking at this photo is like reading your title without knowing Latin. This is my only ribbon in the sound challenge. Posthumous Blue Ribbon.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/></td>', 'Looking at this photo is like reading your title without knowing Latin. This is my only ribbon in the sound challenge. Posthumous Blue Ribbon. ', '2010-10-26 22:27:52.000000', NULL, 1),
(6202175, 915104, 119419, '<td valign="top">I like this, it is nicely imposing, but the sky overpowers the image. I would have the speaker box sharper, especially the gold dome more prominant and more defined. Maybe it''s my monitor...6 for the effort</td>', 'I like this, it is nicely imposing, but the sky overpowers the image. I would have the speaker box sharper, especially the gold dome more prominant and more defined. Maybe it''s my monitor...6 for the effort', '2010-10-27 00:05:24.000000', NULL, 1),
(6202176, 914643, 119419, '<td valign="top">Great image &amp; concept, could do with more spot edits esp that one on the right</td>', 'Great image & concept, could do with more spot edits esp that one on the right', '2010-10-27 00:06:58.000000', NULL, 1),
(6202194, 914856, 55283, '<td valign="top">Congrats! Do we need to send someone over to pick you up off the floor?</td>', 'Congrats! Do we need to send someone over to pick you up off the floor?', '2010-10-27 01:06:00.000000', NULL, 0),
(6202202, 915225, 29440, '<td valign="top">When I see the United States Flag. it conveys to me what the flag represents.  I can hear the words of our National Anthem, God Bless America, and many more sounds associated with the flag. The flag is not respected now as it was during WWII. Citizens do not stand up when the flag passes by. They do not put their hands over their hearts during the playing of the National Anthem. God Bless America</td>', 'When I see the United States Flag. it conveys to me what the flag represents.  I can hear the words of our National Anthem, God Bless America, and many more sounds associated with the flag. The flag is not respected now as it was during WWII. Citizens do not stand up when the flag passes by. They do not put their hands over their hearts during the playing of the National Anthem. God Bless America', '2010-10-27 01:15:08.000000', NULL, 0),
(6202205, 914908, 58430, '<td valign="top">i knew this was you :)</td>', 'i knew this was you :)', '2010-10-27 01:17:37.000000', NULL, 0),
(6202209, 914704, 53814, '<td valign="top">perfect... congratulations Marla.</td>', 'perfect... congratulations Marla.', '2010-10-27 01:21:12.000000', NULL, 0),
(6202229, 915376, 83313, '<td valign="top">A top 10 and a new #2 on your personal hit chart! Woo-hoo!</td>', 'A top 10 and a new #2 on your personal hit chart! Woo-hoo!', '2010-10-27 01:38:16.000000', NULL, 0),
(6202235, 914612, 83313, '<td valign="top">You might want to take that comment from <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30364" rel="nofollow" target="_blank">Ubique</a> and frame it with the shot. That is high praise! I felt the same way about many of the other entries, but he says it perfectly.</td>', 'You might want to take that comment from  Ubique and frame it with the shot. That is high praise! I felt the same way about many of the other entries, but he says it perfectly.', '2010-10-27 01:44:42.000000', NULL, 0),
(6202261, 914806, 30456, '<td valign="top">Congratulations on your first ribbon.  I really like how the pot has that blurred sense of motion as it rattles around on the stove.  Nicely done.</td>', 'Congratulations on your first ribbon.  I really like how the pot has that blurred sense of motion as it rattles around on the stove.  Nicely done.', '2010-10-27 02:20:45.000000', NULL, 0),
