INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6202535, 915191, 18655, '<td valign="top">My favourite in the challenge. Great b/w conversion and subject separation.</td>', 'My favourite in the challenge. Great b/w conversion and subject separation.', '2010-10-27 10:36:49.000000', NULL, 0),
(6202553, 914806, 116649, '<td valign="top">Having set up this exact demo for a science teacher training, I know how difficult it is to capture. It started huge arguments, for while our intent was to demonstrate steam and phase changes, it was brought to out attention that steam was a gas, therefore invisible, and what we were actually seeing was water vapor such as in clouds.  Your image demonstrates the condensation nicely , good job and congratulations on the ribbon!</td>', 'Having set up this exact demo for a science teacher training, I know how difficult it is to capture. It started huge arguments, for while our intent was to demonstrate steam and phase changes, it was brought to out attention that steam was a gas, therefore invisible, and what we were actually seeing was water vapor such as in clouds.  Your image demonstrates the condensation nicely , good job and congratulations on the ribbon!', '2010-10-27 10:59:11.000000', NULL, 0),
(6202557, 915199, 113419, '<td valign="top">The more I look at this the more I LOVE IT!  I looked at it several time during voting.  Can''t figure out why in the hell I only gave it a 7 - I shoulda gave it a 10.<br/>It is beautiful.</td>', 'The more I look at this the more I LOVE IT!  I looked at it several time during voting.  Can''t figure out why in the hell I only gave it a 7 - I shoulda gave it a 10.It is beautiful.', '2010-10-27 11:02:23.000000', NULL, 0),
(6202566, 914865, 7743, '<td valign="top">Clever idea and well executed.</td>', 'Clever idea and well executed.', '2010-10-27 11:15:17.000000', NULL, 0),
(6202600, 914806, 23317, '<td valign="top">Congratulations on the 1st ribbon.  Great idea.  A 10 from me.</td>', 'Congratulations on the 1st ribbon.  Great idea.  A 10 from me.', '2010-10-27 11:52:26.000000', NULL, 0),
(6202633, 915231, 35281, '<td valign="top">I love the expressions on the boy''s faces. The sounds of their celebration jump out of the photograph.  The Order of the Arrow patches caught my attention too.  Well done.</td>', 'I love the expressions on the boy''s faces. The sounds of their celebration jump out of the photograph.  The Order of the Arrow patches caught my attention too.  Well done.', '2010-10-27 12:05:29.000000', NULL, 0),
(6202659, 915199, 53814, '<td valign="top">great technique, I can hear it. congrats on the ubique virtual virtual ribbon.</td>', 'great technique, I can hear it. congrats on the ubique virtual virtual ribbon.', '2010-10-27 12:34:27.000000', NULL, 0),
(6202667, 914856, 119747, '<td valign="top">Well done, should have won IMO!</td>', 'Well done, should have won IMO!', '2010-10-27 12:39:35.000000', NULL, 0),
(6202676, 914865, 29777, '<td valign="top">Thank to the DPC community for the feedback. This is a personal best for me. I feel that a lot of my progress is due to the comments received on DPC.</td>', 'Thank to the DPC community for the feedback. This is a personal best for me. I feel that a lot of my progress is due to the comments received on DPC.', '2010-10-27 12:44:27.000000', NULL, 0),
(6202693, 914979, 113156, '<td valign="top">My Favorite in the challenge, i honestly thought this would surely win, didn''t deserve a sub 6 score.<br/> <br/></td>', 'My Favorite in the challenge, i honestly thought this would surely win, didn''t deserve a sub 6 score. ', '2010-10-27 13:05:20.000000', NULL, 0),
(6202775, 914979, 109353, '<td valign="top">Merci beaucoup John. ;)<br/> <br/>There is four problems with this shot ... in a DPC challenge :<br/>- the motion blur<br/>- washed colors<br/>- centered composition<br/>- the max height size : here is a larger size which puts the viewer in a closer view<br/>another one is the missing jack to connect the guitar :D<br/> <br/>For this one, I really don''t care about the challenge result ... because I was happy to create it !<br/>Thanks for the comments, everyone who liked and everyone who disliked it. ;)</td>', 'Merci beaucoup John. ;) There is four problems with this shot ... in a DPC challenge :- the motion blur- washed colors- centered composition- the max height size : here is a larger size which puts the viewer in a closer viewanother one is the missing jack to connect the guitar :D For this one, I really don''t care about the challenge result ... because I was happy to create it !Thanks for the comments, everyone who liked and everyone who disliked it. ;)', '2010-10-27 14:16:18.000000', NULL, 0),
(6202781, 914856, 55283, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by farra:</b></div><hr/><i> Congrats!! Drinks are on me :) </i></td></tr></table> <br/>Does that go for everybody, or just him?</td>', 'Originally posted by farra: Congrats!! Drinks are on me :)  Does that go for everybody, or just him?', '2010-10-27 14:25:00.000000', NULL, 0),
(6202802, 914704, 50864, '<td valign="top">Thanks for the comments and big thanks to Don for the posthumous blue-that really means a lot.</td>', 'Thanks for the comments and big thanks to Don for the posthumous blue-that really means a lot.', '2010-10-27 15:14:28.000000', NULL, 0),
(6202813, 915191, 38162, '<td valign="top">first rate b&amp;w!  10</td>', 'first rate b&w!  10', '2010-10-27 15:29:47.000000', NULL, 0),
(6202814, 915247, 22689, '<td valign="top">As you can see Goran, some things haven''t changed much ''round here...<br/>I gave a 7 when voting, the idea was really nice, no high sounds here, just a soft blow.<br/>I''m very pleased with your comeback, you''re like fresh air !</td>', 'As you can see Goran, some things haven''t changed much ''round here...I gave a 7 when voting, the idea was really nice, no high sounds here, just a soft blow.I''m very pleased with your comeback, you''re like fresh air !', '2010-10-27 15:31:46.000000', NULL, 0),
(6202897, 914979, 61961, '<td valign="top">Nice blur!</td>', 'Nice blur!', '2010-10-27 17:32:26.000000', NULL, 0),
(6202944, 915123, 23317, '<td valign="top">Couldn''t believe this scored so low.  I don''t know what they''re talking about.  I heard sound when I saw this image.  There has to be music there with her hair flopping around like that.  And look at her beautiful smile... she''s clearly laughing.  7 from me.  Very nice shot Johanna.</td>', 'Couldn''t believe this scored so low.  I don''t know what they''re talking about.  I heard sound when I saw this image.  There has to be music there with her hair flopping around like that.  And look at her beautiful smile... she''s clearly laughing.  7 from me.  Very nice shot Johanna.', '2010-10-27 18:24:17.000000', NULL, 0),
(6202968, 914806, 120058, '<td valign="top">Congrats to your first! You deserve that! Gave it a 9 and it was one of my top pics!</td>', 'Congrats to your first! You deserve that! Gave it a 9 and it was one of my top pics!', '2010-10-27 18:38:33.000000', NULL, 0),
